package pl.edu.pg.eti.kask.aquarium.aquarium.dto;

import jakarta.validation.constraints.NotBlank;
import jakarta.validation.constraints.Positive;
import pl.edu.pg.eti.kask.aquarium.aquarium.entity.Aquarium;

import java.util.UUID;

/**
 * JSON body of a request creating (POST) or modifying (PUT) an aquarium. The identifier is never sent in the body:
 * it is generated by the server or taken from the address.
 */
public record AquariumRequest(@NotBlank String name, @Positive Integer volumeLiters, Double temperature,
                              boolean freshwater) {

    public Aquarium toEntity() {
        return new Aquarium(UUID.randomUUID(), name, volumeLiters, temperature, freshwater);
    }

    public void applyTo(Aquarium aquarium) {
        aquarium.setName(name);
        aquarium.setVolumeLiters(volumeLiters);
        aquarium.setTemperature(temperature);
        aquarium.setFreshwater(freshwater);
    }
}
